import AVFoundation
#if os(iOS)
import UIKit
#endif

/// Sounds and haptics for game events. Respects the Sounds / Haptics settings.
/// Sounds are generated by tools/make_sounds.py.
final class Feedback {
    static let shared = Feedback()

    enum Event {
        case roll, hold, write, crossOut, yamb, gameOver

        var sound: String {
            switch self {
            case .roll: return "roll"
            case .hold: return "hold"
            case .write, .crossOut: return "write"
            case .yamb, .gameOver: return "chime"
            }
        }
    }

    private var players: [String: AVAudioPlayer] = [:]

    private init() {
        #if os(iOS)
        // Ambient: mixes with music and respects the silent switch.
        try? AVAudioSession.sharedInstance().setCategory(.ambient)
        #endif
        for name in ["roll", "hold", "write", "chime"] {
            if let url = Bundle.main.url(forResource: name, withExtension: "wav"),
               let player = try? AVAudioPlayer(contentsOf: url) {
                player.prepareToPlay()
                players[name] = player
            }
        }
    }

    func play(_ event: Event) {
        let settings = AppSettings.shared
        if settings.soundsOn, let player = players[event.sound] {
            player.currentTime = 0
            player.play()
        }
        #if os(iOS)
        if settings.hapticsOn {
            switch event {
            case .roll: UIImpactFeedbackGenerator(style: .medium).impactOccurred()
            case .hold: UISelectionFeedbackGenerator().selectionChanged()
            case .write: UIImpactFeedbackGenerator(style: .light).impactOccurred()
            case .crossOut: UINotificationFeedbackGenerator().notificationOccurred(.warning)
            case .yamb, .gameOver: UINotificationFeedbackGenerator().notificationOccurred(.success)
            }
        }
        #endif
    }
}
